#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_calculate_tat_with_ct_zero(void) {
    struct node *root = NULL;
    float result;

    // Build a process queue with CT fields initialized to 0 (default from insert)
    int ids[] = {1, 2};
    int ats[] = {0, 2};
    int bts[] = {5, 3};
    int priorities[] = {1, 2};
    int size = 2;

    // Use the available helper to build the queue
    root = helper_build_process_queue(ids, ats, bts, priorities, size);
    TEST_ASSERT_NOT_NULL(root);

    // Verify CT is zero for the first node (path condition: ptr->CT == 0)
    TEST_ASSERT_EQUAL_INT(0, root->CT);

    // Call the function under test - this should trigger path 1
    // It will call calculate_ct because CT is zero, then compute TAT for each node
    result = calculate_tat(&root);

    // Assertions
    // After calculate_tat, CT should be non-zero (calculated by calculate_ct)
    TEST_ASSERT_NOT_EQUAL_INT(0, root->CT);
    // TAT should be CT - AT for each node
    struct node *ptr = root;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(ptr->CT - ptr->AT, ptr->TAT);
        ptr = ptr->next;
    }
    // The average TAT should be positive
    TEST_ASSERT_TRUE(result > 0.0f);

    // Cleanup
    helper_cleanup_process_queue(&root);
    TEST_ASSERT_NULL(root);
}


